      title: 'Готово',
      message: `Письмо с подтверждением отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setSubmitted(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: '420px',
