          Подписка на рассылку
        </h2>
        <p style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}>
          Раз в неделю — обновления библиотеки и разбор новых компонентов.
        </p>
      </div>

      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        errorText={emailError}
        helperText="Отписаться можно в один клик из любого письма."
      />

      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>

      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </form>
  );
}

